# pure-python keccak-256
def keccak256(msg: bytes) -> bytes:
    RC=[0x0000000000000001,0x0000000000008082,0x800000000000808A,0x8000000080008000,
        0x000000000000808B,0x0000000080000001,0x8000000080008081,0x8000000000008009,
        0x000000000000008A,0x0000000000000088,0x0000000080008009,0x000000008000000A,
        0x000000008000808B,0x800000000000008B,0x8000000000008089,0x8000000000008003,
        0x8000000000008002,0x8000000000000080,0x000000000000800A,0x800000008000000A,
        0x8000000080008081,0x8000000000008080,0x0000000080000001,0x8000000080008008]
    r=[[0,36,3,41,18],[1,44,10,45,2],[62,6,43,15,61],[28,55,25,21,56],[27,20,39,8,14]]
    def rol(x,n): return ((x<<n)|(x>>(64-n)))&0xffffffffffffffff
    rate=136
    st=[0]*25
    msg=bytearray(msg)
    msg+=b'\x01'
    while len(msg)%rate!=0: msg.append(0)
    msg[-1]^=0x80
    for off in range(0,len(msg),rate):
        blk=msg[off:off+rate]
        for i in range(rate//8):
            st[i]^=int.from_bytes(blk[i*8:i*8+8],'little')
        for rnd in range(24):
            C=[st[x]^st[x+5]^st[x+10]^st[x+15]^st[x+20] for x in range(5)]
            D=[C[(x-1)%5]^rol(C[(x+1)%5],1) for x in range(5)]
            for x in range(5):
                for y in range(5): st[x+5*y]^=D[x]
            B=[0]*25
            for x in range(5):
                for y in range(5):
                    B[y+5*((2*x+3*y)%5)]=rol(st[x+5*y],r[x][y])
            for x in range(5):
                for y in range(5):
                    st[x+5*y]=B[x+5*y]^((~B[(x+1)%5+5*y])&B[(x+2)%5+5*y])
            st[0]^=RC[rnd]
    out=b''.join(st[i].to_bytes(8,'little') for i in range(25))
    return out[:32]
def sel(sig):
    return int.from_bytes(keccak256(sig.encode())[:4],'big')
